VOCAB_CONTENT = {}
for patch in VOCAB_PATCHES:
    current = Path(patch['path']).read_text()
    for replacement in reversed(patch['replacements']):
        assert current.count(replacement['after']) == 1, f"{patch['path']}: vocabulary hook changed"
        current = current.replace(replacement['after'], replacement['before'], 1)
    VOCAB_CONTENT[patch['path']] = current
